// Two readings into what both views draw: per-process CPU, the tree, the totals.

import type { ProcRow, Snapshot } from '../types'
import type { Platform, Proc, Sample } from './stats'

// A build can start hundreds of workers; the pane needs no more than this.
export const MAX_ROWS = 500

// The engine, the processes under it (undefined when the table cannot be read), and the detached
// processes this session started (left out where they are not tracked).
export type Timed = { engine: Sample; children?: Proc[]; detached?: Proc[]; wallMs: number }

// CPU a process spent since the last reading, and as a share of one core. A pid
// whose process is younger than the one seen before was reused: a new process.
// One first seen (new, reused, or found late by a slow scan) shows its average over its
// life; only the share of its CPU that falls in this reading's window counts as delta.
export const procCpu = (now: Proc, was: Proc | undefined, elapsed: number) => {
  const isSame = was !== undefined && now.uptimeSeconds >= was.uptimeSeconds - 1
  if (isSame) {
    const delta = Math.max(0, now.cpuSeconds - was.cpuSeconds)

    return { delta, percent: (delta / elapsed) * 100 }
  }
  const window = Math.max(1, now.uptimeSeconds)

  return { delta: now.cpuSeconds * Math.min(1, elapsed / window), percent: (now.cpuSeconds / window) * 100 }
}

// Depth-first from the engine, each level by pid.
export const treeOrder = (procs: Proc[], root: number) => {
  const byParent = new Map<number, Proc[]>()
  for (const proc of procs) byParent.set(proc.ppid, [...(byParent.get(proc.ppid) ?? []), proc])
  for (const list of byParent.values()) list.sort((a, b) => a.pid - b.pid)
  const ordered: { proc: Proc; depth: number }[] = []
  const seen = new Set<number>()
  const visit = (pid: number, depth: number) => {
    for (const proc of byParent.get(pid) ?? []) {
      if (seen.has(proc.pid)) continue
      seen.add(proc.pid)
      ordered.push({ proc, depth })
      visit(proc.pid, depth + 1)
    }
  }
  visit(root, 0)
  // A process whose parent ended between reads is kept, at the top level.
  for (const proc of procs) if (!seen.has(proc.pid)) ordered.push({ proc, depth: 0 })

  return ordered
}

// A parent no process has, for forestOrder's roots.
const FOREST_ROOT = -1

// Processes as a forest: each whose parent is not among them is a root, roots by pid.
export const forestOrder = (procs: Proc[]) => {
  const pids = new Set(procs.map(proc => proc.pid))
  const byPid = new Map(procs.map(proc => [proc.pid, proc]))
  const rooted = procs.map(proc => (pids.has(proc.ppid) ? proc : { ...proc, ppid: FOREST_ROOT }))

  return treeOrder(rooted, FOREST_ROOT).map(({ proc, depth }) => ({ proc: byPid.get(proc.pid)!, depth }))
}

export const buildSnapshot = (
  platform: Platform,
  pid: number,
  now: Timed,
  before: Timed | undefined,
): Snapshot => {
  const elapsed = before ? (now.wallMs - before.wallMs) / 1000 : 0
  const isMeasured = before !== undefined && elapsed > 0
  const was = new Map([...(before?.children ?? []), ...(before?.detached ?? [])].map(proc => [proc.pid, proc]))
  const canCompare = isMeasured && before?.children !== undefined && now.children !== undefined
  let childDelta = 0
  let detachedDelta = 0
  const toRow = ({ proc, depth }: { proc: Proc; depth: number }, isDetached: boolean): ProcRow => {
    const cpu = canCompare ? procCpu(proc, was.get(proc.pid), elapsed) : undefined
    childDelta += cpu?.delta ?? 0
    if (isDetached) detachedDelta += cpu?.delta ?? 0

    return {
      pid: proc.pid,
      ppid: proc.ppid,
      depth,
      command: proc.command,
      rssKb: proc.rssKb,
      cpuPercent: cpu ? cpu.percent : null,
      uptimeSeconds: proc.uptimeSeconds,
      startMs: Math.round(now.wallMs - proc.uptimeSeconds * 1000),
      ...(isDetached ? { detached: true as const } : {}),
    }
  }
  // The tree under Claude Code, then the detached processes; the detached ones only with the tree.
  const detachedRows = now.children ? forestOrder(now.detached ?? []).map(each => toRow(each, true)) : []
  const rows = now.children ? [...treeOrder(now.children, pid).map(each => toRow(each, false)), ...detachedRows] : null

  return {
    platform,
    pid,
    engine: {
      rssKb: now.engine.rssKb,
      peakKb: now.engine.peakKb,
      cpuPercent:
        isMeasured && before
          ? (Math.max(0, now.engine.cpuSeconds - before.engine.cpuSeconds) / elapsed) * 100
          : null,
      uptimeSeconds: now.engine.uptimeSeconds,
    },
    children: rows,
    childCount: rows?.length ?? 0,
    childKb: rows?.reduce((sum, row) => sum + row.rssKb, 0) ?? 0,
    childCpuPercent: canCompare ? (childDelta / elapsed) * 100 : null,
    detachedCount: detachedRows.length,
    detachedKb: detachedRows.reduce((sum, row) => sum + row.rssKb, 0),
    detachedCpuPercent: canCompare ? (detachedDelta / elapsed) * 100 : null,
  }
}

// What the pane is handed: the totals over every process, the rows capped.
export const capRows = (snapshot: Snapshot): Snapshot => ({
  ...snapshot,
  children: snapshot.children?.slice(0, MAX_ROWS) ?? null,
})

files.hooks/report.ts:
// The `/proc-stats report` text: what the person and the model read about the session, from current state.

import type { AlertState, Origins, Point, ProcRow, Reading } from '../types'
import { worse } from './alerts'
import { formatBytes, formatDuration, formatPercent } from './format'
import { originLabel, originOf } from './origin'
import { labelOf, subtotals } from './view'

// How many processes the report names, heaviest (most memory) first.
export const HEAVIEST = 5
// How many detached processes the report lists, heaviest first.
export const DETACHED_LISTED = 10
// A command is cut to this many code points.
const COMMAND_MAX = 80

export type ReportInput = {
  reading: Reading
  points: Point[]
  alerts: AlertState
  origins: Origins
  // ms since the epoch
  now: number
  historyMinutes: number
}

const PLATFORMS: Record<string, string> = { linux: 'Linux', mac: 'macOS', windows: 'Windows' }

const cut = (text: string) => {
  const chars = Array.from(text)

  return chars.length > COMMAND_MAX ? `${chars.slice(0, COMMAND_MAX - 1).join('')}…` : text
}

const ago = (now: number, t: number) => `${formatDuration((now - t) / 1000)} ago`

const sum = (a: number | null, b: number | null) => (a === null || b === null ? null : a + b)

// The first point holding the highest value: when the peak was reached.
const peakOf = (points: Point[], pick: (point: Point) => number) =>
  points.reduce<Point | null>((best, point) => (best === null || pick(point) > pick(best) ? point : best), null)

// Most memory first, then most CPU, then the lower pid.
const byWeight = (rows: ProcRow[]) =>
  [...rows].sort((a, b) => b.rssKb - a.rssKb || (b.cpuPercent ?? 0) - (a.cpuPercent ?? 0) || a.pid - b.pid)

// One listed process: its figures, command and origin, and (where asked) whether it is detached. Not
// numbered: Claude Code shows the report as Markdown, where a numbered line starts a list that runs on.
const processLine = (row: ProcRow, origins: Origins, isDetachedShown: boolean) => {
  const origin = originOf(origins, row)
  const from = origin ? ` · ${originLabel(origin)}` : ''
  const detached = isDetachedShown && row.detached ? ' · detached' : ''

  return `  ${formatBytes(row.rssKb)} · ${formatPercent(row.cpuPercent)} CPU · pid ${row.pid} · ${cut(labelOf(row.command))}${from}${detached}`
}

// A subtotal in words: `2 child processes 20MB, 1.0% CPU`.
const subtotalText = (count: number, noun: string, kb: number, cpuPercent: number | null) =>
  `${count} ${noun} ${formatBytes(kb)}, ${formatPercent(cpuPercent)} CPU`

export const reportText = ({ reading, points, alerts, origins, now, historyMinutes }: ReportInput) => {
  const snapshot = reading.snapshot
  if (!snapshot) return `report: ${reading.error ?? 'no reading yet'}`
  const { engine, children, childCount, childKb, childCpuPercent } = snapshot
  const lines = [
    `report · ${PLATFORMS[snapshot.platform] ?? snapshot.platform} · Claude Code pid ${snapshot.pid} · up ${formatDuration(engine.uptimeSeconds)}`,
  ]

  const own = `Claude Code ${formatBytes(engine.rssKb)}, ${formatPercent(engine.cpuPercent)} CPU`
  const { under, detached } = subtotals(snapshot)
  if (children === null) lines.push(`Now: ${own} · child processes unknown (the process table could not be read)`)
  else if (childCount === 0) lines.push(`Now: ${own} · no child processes`)
  else {
    const parts = [
      under.count === 0
        ? 'no child processes'
        : subtotalText(under.count, under.count === 1 ? 'child process' : 'child processes', under.kb, under.cpuPercent),
      ...(detached.count > 0 ? [subtotalText(detached.count, 'detached', detached.kb, detached.cpuPercent)] : []),
      `total ${formatBytes(engine.rssKb + childKb)}, ${formatPercent(sum(engine.cpuPercent, childCpuPercent))} CPU`,
    ]
    lines.push(`Now: ${own} · ${parts.join(' · ')}`)
  }
  if (snapshot.detachedOff !== undefined) lines.push(snapshot.detachedOff)

  const memPeak = peakOf(points, point => point.memKb)
  const cpuPeak = peakOf(points, point => point.cpuPct)
  lines.push(
    memPeak && cpuPeak
      ? `Peaks in the last ${historyMinutes} min: memory ${formatBytes(memPeak.memKb)} ${ago(now, memPeak.t)} · CPU ${formatPercent(cpuPeak.cpuPct)} ${ago(now, cpuPeak.t)}`
      : `Peaks in the last ${historyMinutes} min: no history yet`,
  )

  if (children && children.length > 0) {
    lines.push('Heaviest processes:')
    byWeight(children).slice(0, HEAVIEST).forEach(row => lines.push(processLine(row, origins, true)))
    const detachedRows = children.filter(row => row.detached)
    if (detachedRows.length > 0) {
      lines.push(
        detached.count > DETACHED_LISTED ? `Detached processes (${DETACHED_LISTED} of ${detached.count}):` : 'Detached processes:',
      )
      byWeight(detachedRows).slice(0, DETACHED_LISTED).forEach(row => lines.push(processLine(row, origins, false)))
    }
  }

  const { mem, cpu } = alerts.levels
  const level = worse(mem, cpu)
  lines.push(level === 'none' ? 'Marker: none' : `Marker: ${level === 'alert' ? '🔴' : '🟡'} ${level} (memory ${mem}, CPU ${cpu})`)

  const recent = alerts.recent ?? []
  if (recent.length === 0) lines.push('Recent alerts: none')
  else {
    lines.push('Recent alerts:')
    for (const toast of [...recent].reverse()) lines.push(`  ${ago(now, toast.t)} · ${toast.text}`)
  }

  return lines.join('\n')
}

files.hooks/status.ts:
// The status line under the prompt.

import type { Snapshot } from '../types'
import { formatBytes, formatDuration, formatPair, formatPercent } from './format'

// The share of the processes the session started (under Claude Code or detached) shows only while there
// are any; `?` when the table could not be read.
export const statusLine = (snapshot: Snapshot, showChildren = true) => {
  const { engine, children, childCpuPercent } = snapshot
  // Without them, or with none running, Claude Code's own figures alone.
  const hasChildren = showChildren && (children === null || snapshot.childCount > 0)
  let cpu = '…'
  if (engine.cpuPercent !== null) {
    const own = engine.cpuPercent.toFixed(1)
    cpu = hasChildren
      ? `(${own} + ${childCpuPercent === null ? '?' : childCpuPercent.toFixed(1)})%`
      : formatPercent(engine.cpuPercent)
  }
  const childKb = children === null ? undefined : snapshot.childKb

  return `mem ${formatPair(engine.rssKb, hasChildren ? childKb : 0)} · peak ${formatBytes(engine.peakKb)} · cpu ${cpu} · up ${formatDuration(engine.uptimeSeconds)}`
}

files.hooks/stop.ts:
// Stopping a process and what it started: whom to stop, how, and what to say.

import type { Selected, Snapshot, StopState } from '../types'
import { parseProcStat, parsePsTime } from './stats'
import { fit, isSelected, START_TOLERANCE_MS } from './view'

// How long after a stop the pane checks what is still running.
export const STOP_CHECK_MS = 3000
// How many times a check with no reading (or no liveness) tries again before offering force stop.
export const STOP_CHECK_TRIES = 10

// The process and everything below it, deepest first (it last); null when it is not a listed child:
// Claude Code, ended, or a pid now used by another process.
export const stopTargets = (snapshot: Snapshot, selected: Selected): number[] | null => {
  const rows = snapshot.children ?? []
  const index = rows.findIndex(row => isSelected(row, selected))
  if (selected.pid === snapshot.pid || index < 0) return null
  const depth = rows[index]!.depth
  let end = index + 1
  while (end < rows.length && rows[end]!.depth > depth) end++

  return rows
    .slice(index, end)
    .sort((a, b) => b.depth - a.depth)
    .map(row => row.pid)
}

// Each pid's start in the reading, aligned with pids.
export const startsOf = (snapshot: Snapshot, pids: number[]) =>
  pids.map(pid => snapshot.children?.find(row => row.pid === pid)?.startMs ?? NaN)

// SIGTERM (or SIGKILL) to every pid in order. On Windows the first stop takes the tree from its root,
// the last pid; a force stop names each survivor, since one left outside the tree is not reached from the root.
export const killArgv = (platform: string, pids: number[], isForce: boolean) =>
  platform === 'windows'
    ? [
        'taskkill',
        '/T',
        ...(isForce
          ? ['/F', ...pids.flatMap(pid => ['/PID', String(pid)])]
          : ['/PID', String(pids[pids.length - 1])]),
      ]
    : ['kill', isForce ? '-KILL' : '-TERM', ...pids.map(String)]

// A failed signal whose every line says the process had already ended: no failure.
export const isAlreadyEnded = (stderr: string) => {
  const lines = stderr.split(/\r?\n/).filter(line => line.trim() !== '')

  return lines.length > 0 && lines.every(line => /No such process|not found/i.test(line))
}

// A process seen running: its pid and start (ms), placed as the readings place it.
export type Observed = { pid: number; startMs: number }

// The targets (in their order) still running: observed with a start within the tolerance of the
// recorded one. A pid with another start is a new process that reuses it.
export const aliveFrom = (targets: Observed[], observed: Observed[]) =>
  targets
    .filter(target => observed.some(seen => seen.pid === target.pid && Math.abs(seen.startMs - target.startMs) <= START_TOLERANCE_MS))
    .map(target => target.pid)

// Linux: /proc/<pid>/stat with /proc/uptime; a zombie has ended (and cannot be signalled), so it is null.
export const linuxObserved = (pid: number, stat: string, uptime: string, wallMs: number): Observed | null => {
  const state = stat.slice(stat.lastIndexOf(')') + 2).split(' ')[0]
  if (state === 'Z') return null
  const { uptimeSeconds } = parseProcStat(stat, uptime)

  return Number.isFinite(uptimeSeconds) ? { pid, startMs: Math.round(wallMs - uptimeSeconds * 1000) } : null
}

const fieldLines = (text: string) =>
  text
    .split(/\r?\n/)
    .map(line => line.trim().split(/\s+/))
    .filter(fields => fields.length >= 2 && /^\d+$/.test(fields[0]!))

// macOS: ps lists the pids still running; it exits 1 when it lists none, so only its output counts.
export const macLivenessArgv = (pids: number[]) => ['ps', '-o', 'pid=,etime=', '-p', pids.join(',')]

export const parseMacLiveness = (stdout: string, wallMs: number): Observed[] =>
  fieldLines(stdout).map(([pid, etime]) => ({ pid: Number(pid), startMs: Math.round(wallMs - parsePsTime(etime!) * 1000) }))

// Windows: `<pid> <ageSeconds>` per process still running; ended ones are left out silently.
export const windowsLivenessScript = (pids: number[]) =>
  [
    `$c = [cultureinfo]::InvariantCulture`,
    `$now = Get-Date`,
    `Get-Process -Id ${pids.join(',')} -ErrorAction SilentlyContinue | ForEach-Object {` +
      ` [string]::Format($c, '{0} {1:F0}', $_.Id, ($now - $_.StartTime).TotalSeconds) }`,
  ].join('; ')

export const parseWindowsLiveness = (stdout: string, wallMs: number): Observed[] =>
  fieldLines(stdout)
    .map(([pid, age]) => ({ pid: Number(pid), startMs: Math.round(wallMs - Number(age) * 1000) }))
    .filter(seen => Number.isFinite(seen.startMs))

const name = (stop: StopState) => fit(stop.label, 48).trimEnd()

export const confirmText = (stop: StopState) => {
  const started = stop.pids.length - 1
  const tail = started === 0 ? '' : ` and the ${started} process${started === 1 ? '' : 'es'} it started`

  return `Stop ${name(stop)} (pid ${stop.pid})${tail}?`
}

export const outcomeText = (stop: StopState, remaining: number[]) =>
  remaining.length === 0
    ? `Stopped ${name(stop)} (pid ${stop.pid}) · /proc-stats`
    : `${name(stop)} (pid ${stop.pid}): ${remaining.length} of ${stop.pids.length} processes still running · /proc-stats`

files.hooks/view.ts:
// The pane's rows as text: labels, cells, tree or sorted order, collapsing, selection and details.

import type { Origins, PaneState, ProcRow, Selected, Snapshot, SortMode } from '../types'
import { formatBytes, formatDuration, formatPercent } from './format'
import { originDetail, originOf } from './origin'

export const EMPTY_PANE: PaneState = { sort: 'tree', collapsed: [], selected: null, stop: null }

// A process's start, taken from readings, can move by a second or so; further apart is another process.
export const START_TOLERANCE_MS = 2000

const SORTS: SortMode[] = ['tree', 'cpu', 'mem', 'time']

// Whitespace runs, newlines included, become one space.
export const oneLine = (text: string) => text.replace(/\s+/g, ' ').trim()

const EVAL = " && eval '"

// Claude Code runs a Bash command as `bash -c source <…/shell-snapshots/…> … && eval '<command>' < /dev/null && …`,
// a `'` inside written `'"'"'`. The command, or null for any other process.
export const unwrapCommand = (command: string): string | null => {
  const start = command.indexOf(EVAL)
  if (start < 0 || !command.includes('shell-snapshots/')) return null
  let rest = command.slice(start + EVAL.length)
  let inner = ''
  for (;;) {
    const quote = rest.indexOf("'")
    if (quote < 0) return null
    inner += rest.slice(0, quote)
    rest = rest.slice(quote + 1)
    if (!rest.startsWith(`"'"'`)) return inner
    inner += "'"
    rest = rest.slice(4)
  }
}

// What a row is called: `$ <command>` for a Bash command Claude Code ran, else the command line.
export const labelOf = (command: string) => {
  const inner = unwrapCommand(command)

  return inner === null ? oneLine(command) : `$ ${oneLine(inner)}`
}

// Cut to `width` code points with … when cut, then padded to `width`.
export const fit = (text: string, width: number, alignRight = false) => {
  const chars = Array.from(text)
  const kept = chars.length > width ? [...chars.slice(0, Math.max(0, width - 1)), '…'] : chars
  const pad = ' '.repeat(Math.max(0, width - kept.length))

  return alignRight ? pad + kept.join('') : kept.join('') + pad
}

// Tree lines for rows in tree order: `├ ` or `└ ` before each, and `│ ` under
// every ancestor that has a sibling still to come.
export const treePrefixes = (rows: { depth: number }[]) => {
  const isLastAt: boolean[] = []

  return rows.map(({ depth }, index) => {
    const next = rows.slice(index + 1).find(row => row.depth <= depth)
    const isLast = next === undefined || next.depth < depth
    const prefix = isLastAt.slice(0, depth).map(last => (last ? '  ' : '│ ')).join('')
    isLastAt[depth] = isLast

    return `${prefix}${isLast ? '└' : '├'} `
  })
}

export type ViewRow = {
  row: ProcRow
  label: string
  // Tree lines in the tree view; empty when sorted.
  prefix: string
  // The parent's label in sorted views; null in the tree.
  parent: string | null
  // The row's own figures, or its subtree's while collapsed.
  rssKb: number
  cpuPercent: number | null
  hasChildren: boolean
  isCollapsed: boolean
}

// The index just past a row's subtree (rows are in tree order).
const subtreeEnd = (rows: ProcRow[], index: number) => {
  const depth = rows[index]!.depth
  let end = index + 1
  while (end < rows.length && rows[end]!.depth > depth) end++

  return end
}

const sumCpu = (rows: ProcRow[]) =>
  rows.some(row => row.cpuPercent === null) ? null : rows.reduce((sum, row) => sum + (row.cpuPercent ?? 0), 0)

// A process's label, or its pid when it is not among the rows (past the cap, or ended).
const labelIn = (rows: ProcRow[], pid: number) => {
  const found = rows.find(row => row.pid === pid)

  return found ? labelOf(found.command) : `pid ${pid}`
}

const sortKey: Record<Exclude<SortMode, 'tree'>, (row: ProcRow) => number> = {
  cpu: row => row.cpuPercent ?? -1,
  mem: row => row.rssKb,
  time: row => row.uptimeSeconds,
}

export const viewRows = (snapshot: Snapshot, state: PaneState): ViewRow[] => {
  const rows = snapshot.children ?? []
  const labels = new Map(rows.map(row => [row.pid, labelOf(row.command)]))
  const label = (pid: number) => labels.get(pid) ?? labelIn(rows, pid)
  const sort = state.sort
  if (sort !== 'tree') {
    const key = sortKey[sort]

    return [...rows]
      .sort((a, b) => key(b) - key(a) || a.pid - b.pid)
      .map(row => ({
        row,
        label: label(row.pid),
        prefix: '',
        parent: row.ppid === snapshot.pid ? 'Claude Code' : row.detached && !labels.has(row.ppid) ? 'detached' : label(row.ppid),
        rssKb: row.rssKb,
        cpuPercent: row.cpuPercent,
        hasChildren: false,
        isCollapsed: false,
      }))
  }
  const visible: ViewRow[] = []
  for (let index = 0; index < rows.length; ) {
    const row = rows[index]!
    const end = subtreeEnd(rows, index)
    const hasChildren = end > index + 1
    const isCollapsed = hasChildren && state.collapsed.includes(row.pid)
    const span = isCollapsed ? rows.slice(index, end) : [row]
    visible.push({
      row,
      label: label(row.pid),
      prefix: '',
      parent: null,
      rssKb: span.reduce((sum, each) => sum + each.rssKb, 0),
      cpuPercent: sumCpu(span),
      hasChildren,
      isCollapsed,
    })
    index = isCollapsed ? end : index + 1
  }
  // The tree and the detached group (which follows it) each draw their own lines.
  const prefixes = [
    ...treePrefixes(visible.filter(view => !view.row.detached).map(view => view.row)),
    ...treePrefixes(visible.filter(view => view.row.detached).map(view => view.row)),
  ]

  return visible.map((view, index) => ({ ...view, prefix: prefixes[index] ?? '' }))
}

export const isSelected = (row: { pid: number; startMs: number }, selected: Selected | null) =>
  selected !== null && selected.pid === row.pid && Math.abs(selected.startMs - row.startMs) <= START_TOLERANCE_MS

export const cycleSort = (sort: SortMode): SortMode => SORTS[(SORTS.indexOf(sort) + 1) % SORTS.length]!

export const toggleCollapsed = (collapsed: number[], pid: number) =>
  collapsed.includes(pid) ? collapsed.filter(each => each !== pid) : [...collapsed, pid]

// Forgets what names an ended process. Claude Code's row stays selectable; a stop past its confirmation
// is kept (a process it left running may run outside the tree, unlisted), cleared by f or n; an unreadable
// table changes nothing.
export const pruneState = (state: PaneState, snapshot: Snapshot): PaneState => {
  const rows = snapshot.children
  if (rows === null) return state
  const isListed = (chosen: Selected) => rows.some(row => isSelected(row, chosen))
  const selected =
    state.selected && (state.selected.pid === snapshot.pid || isListed(state.selected)) ? state.selected : null
  const stop = state.stop && (state.stop.phase !== 'confirm' || isListed(state.stop)) ? state.stop : null
  const collapsed = state.collapsed.filter(pid => rows.some(row => row.pid === pid))

  return { ...state, selected, collapsed, stop }
}

const clockTime = (ms: number) => {
  const date = new Date(ms)

  return [date.getHours(), date.getMinutes(), date.getSeconds()].map(part => String(part).padStart(2, '0')).join(':')
}

// The selected row's full command, then its facts; null with nothing (listed) selected.
export const detailLines = (snapshot: Snapshot, selected: Selected | null, origins?: Origins): string[] | null => {
  if (selected === null) return null
  const { engine } = snapshot
  if (selected.pid === snapshot.pid) {
    return [
      `Claude Code · pid ${snapshot.pid} · ${formatBytes(engine.rssKb)} · ${formatPercent(engine.cpuPercent)} · up ${formatDuration(engine.uptimeSeconds)}`,
    ]
  }
  const rows = snapshot.children ?? []
  const row = rows.find(each => isSelected(each, selected))
  if (!row) return null
  const parent = row.ppid === snapshot.pid ? 'Claude Code' : labelIn(rows, row.ppid)

  const lines = [
    oneLine(row.command),
    `pid ${row.pid} · parent ${row.ppid} (${parent}) · started ${clockTime(row.startMs)} · ${formatBytes(row.rssKb)} · ${formatPercent(row.cpuPercent)} · up ${formatDuration(row.uptimeSeconds)}`,
  ]
  if (row.detached) lines.push('detached: started in this session, no longer under Claude Code')
  const origin = origins ? originOf(origins, row) : null
  if (origin) return [...lines, originDetail(origin)]
  if (origins && unwrapCommand(row.command) !== null) return [...lines, 'origin unknown']

  return lines
}

export type TotalLine = { label: string; mem: string; cpu: string }

export type Subtotal = { count: number; kb: number; cpuPercent: number | null }

// The processes under Claude Code and the detached ones, apart. A reading saved before detached
// processes were tracked has none detached.
export const subtotals = (snapshot: Snapshot): { under: Subtotal; detached: Subtotal } => {
  const { childCount, childKb, childCpuPercent } = snapshot
  const { detachedCount = 0, detachedKb = 0, detachedCpuPercent = 0 } = snapshot
  const underCpu = childCpuPercent === null || detachedCpuPercent === null ? null : Math.max(0, childCpuPercent - detachedCpuPercent)

  return {
    under: { count: childCount - detachedCount, kb: childKb - detachedKb, cpuPercent: underCpu },
    detached: { count: detachedCount, kb: detachedKb, cpuPercent: detachedCpuPercent },
  }
}

// Each subtotal while it has processes, then the session total, when there are any.
export const totalLines = (snapshot: Snapshot): TotalLine[] => {
  const { engine, children, childCount, childKb, childCpuPercent } = snapshot
  if (children === null || childCount === 0) return []
  const both = engine.cpuPercent !== null && childCpuPercent !== null ? engine.cpuPercent + childCpuPercent : null
  const { under, detached } = subtotals(snapshot)
  const line = (label: string, subtotal: Subtotal) => ({
    label: `${label} (${subtotal.count})`,
    mem: formatBytes(subtotal.kb),
    cpu: formatPercent(subtotal.cpuPercent),
  })

  return [
    ...(under.count > 0 ? [line('Child processes', under)] : []),
    ...(detached.count > 0 ? [line('Detached', detached)] : []),
    { label: 'Total', mem: formatBytes(engine.rssKb + childKb), cpu: formatPercent(both) },
  ]
}

// One dim line under the rows: why there are none, or how many are left out.
export const noteLine = (snapshot: Snapshot) => {
  if (snapshot.children === null) return 'Child process list unavailable'
  if (snapshot.childCount === 0) return 'No child processes'
  const hidden = snapshot.childCount - snapshot.children.length

  return hidden > 0 ? `… ${hidden} more` : null
}

